DROP VIEW IF EXISTS `issuedbook_view`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `issuedbook_view` AS select `member`.`initials` AS `initials`,`member`.`surname` AS `surname`,`member`.`userid` AS `userid`,`catalog`.`title` AS `title`,`catalog`.`isbn` AS `isbn`,`issuedbook`.`booknumber` AS `booknumber`,`issuedbook`.`IssuesDate` AS `IssuesDate`,`issuedbook`.`ReturnDate` AS `ReturnDate`,`issuedbook`.`fine` AS `fine`,`issuedbook`.`RetrunStatus` AS `RetrunStatus`,`issuedbook`.`noofrenew` AS `noofrenew` from ((`member` join `issuedbook` on((`member`.`cardnumber` = `issuedbook`.`membernumber`))) join `catalog` on((`catalog`.`booknumber` = `issuedbook`.`booknumber`)));

